-- ============================================================
-- STEP 3: Remaining Tables (26-101) with RLS
-- ============================================================

-- WhatsApp settings policy
DO $$ BEGIN CREATE POLICY "whatsapp_settings_select" ON public.whatsapp_settings FOR SELECT USING (company_id = get_user_company_id() OR is_super_admin(auth.uid())); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE POLICY "whatsapp_settings_manage" ON public.whatsapp_settings FOR ALL USING (company_id = get_user_company_id() AND (has_company_role(auth.uid(), 'owner') OR has_company_role(auth.uid(), 'admin'))); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- eCommerce
CREATE TABLE IF NOT EXISTS public.ecommerce_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, customer_id UUID REFERENCES public.customers(id), external_order_id TEXT, external_source TEXT, status TEXT DEFAULT 'pending', total_amount NUMERIC, currency TEXT DEFAULT 'SAR', items JSONB, shipping_address JSONB, billing_address JSONB, payment_method TEXT, payment_status TEXT DEFAULT 'pending', tracking_number TEXT, carrier TEXT, estimated_delivery TIMESTAMPTZ, delivered_at TIMESTAMPTZ, notes TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.ecommerce_returns (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, order_id UUID REFERENCES public.ecommerce_orders(id), customer_id UUID REFERENCES public.customers(id), return_number TEXT, reason TEXT, reason_category TEXT, description TEXT, status TEXT DEFAULT 'pending', refund_amount NUMERIC, refund_status TEXT DEFAULT 'pending', refunded_at TIMESTAMPTZ, approved_by UUID, approved_at TIMESTAMPTZ, photos TEXT[], created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());

-- Real Estate
CREATE TABLE IF NOT EXISTS public.properties (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, title TEXT NOT NULL, title_en TEXT, description TEXT, property_type TEXT, status TEXT DEFAULT 'available', price NUMERIC, price_type TEXT, currency TEXT DEFAULT 'SAR', city TEXT, district TEXT, address TEXT, area_sqm NUMERIC, bedrooms INTEGER, bathrooms INTEGER, amenities TEXT[], images TEXT[], location JSONB, owner_id UUID, manager_id UUID, external_id TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.property_viewings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, property_id UUID REFERENCES public.properties(id), customer_id UUID REFERENCES public.customers(id), scheduled_at TIMESTAMPTZ, status TEXT DEFAULT 'scheduled', assigned_to UUID, duration_minutes INTEGER DEFAULT 30, notes TEXT, feedback TEXT, rating INTEGER, confirmed_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, cancelled_at TIMESTAMPTZ, cancellation_reason TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());

-- Healthcare
