-- Restaurant
CREATE TABLE IF NOT EXISTS public.restaurant_reservations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, customer_id UUID REFERENCES public.customers(id), reservation_number TEXT, party_size INTEGER NOT NULL, scheduled_at TIMESTAMPTZ NOT NULL, duration_minutes INTEGER DEFAULT 90, table_number TEXT, status TEXT DEFAULT 'pending', special_requests TEXT, occasion TEXT, dietary_restrictions TEXT[], reminder_sent BOOLEAN DEFAULT false, no_show BOOLEAN DEFAULT false, confirmed_at TIMESTAMPTZ, seated_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, cancelled_at TIMESTAMPTZ, cancellation_reason TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.restaurant_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, customer_id UUID REFERENCES public.customers(id), reservation_id UUID REFERENCES public.restaurant_reservations(id), order_number TEXT, order_type TEXT DEFAULT 'delivery', status TEXT DEFAULT 'pending', items JSONB, subtotal NUMERIC, tax NUMERIC, discount NUMERIC DEFAULT 0, delivery_fee NUMERIC DEFAULT 0, total_amount NUMERIC, currency TEXT DEFAULT 'SAR', payment_method TEXT, payment_status TEXT DEFAULT 'pending', delivery_address JSONB, delivery_instructions TEXT, estimated_ready TIMESTAMPTZ, estimated_delivery TIMESTAMPTZ, prepared_at TIMESTAMPTZ, picked_up_at TIMESTAMPTZ, delivered_at TIMESTAMPTZ, driver_id UUID, driver_name TEXT, driver_phone TEXT, rating INTEGER, feedback TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());

-- Education
CREATE TABLE IF NOT EXISTS public.education_courses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, title TEXT NOT NULL, title_ar TEXT, description TEXT, description_ar TEXT, course_code TEXT, instructor_name TEXT, instructor_name_ar TEXT, start_date TIMESTAMPTZ, end_date TIMESTAMPTZ, duration_hours INTEGER, max_participants INTEGER, current_participants INTEGER DEFAULT 0, price NUMERIC, currency TEXT DEFAULT 'SAR', location TEXT, is_online BOOLEAN DEFAULT false, meeting_link TEXT, schedule JSONB, status TEXT DEFAULT 'active', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
