-- Maintenance
CREATE TABLE IF NOT EXISTS public.maintenance_tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, customer_id UUID REFERENCES public.customers(id), property_id UUID REFERENCES public.properties(id), ticket_number TEXT, title TEXT, description TEXT, category TEXT, subcategory TEXT, priority TEXT DEFAULT 'medium', urgency TEXT, status TEXT DEFAULT 'open', assigned_to UUID, assigned_at TIMESTAMPTZ, scheduled_at TIMESTAMPTZ, started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, estimated_cost NUMERIC, approved_cost NUMERIC, actual_cost NUMERIC, requires_approval BOOLEAN DEFAULT false, approved_by UUID, approved_at TIMESTAMPTZ, resolution TEXT, photos TEXT[], customer_rating INTEGER, customer_feedback TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());

-- Marketing
CREATE TABLE IF NOT EXISTS public.marketing_campaigns (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT, campaign_type TEXT NOT NULL DEFAULT 'general', status TEXT NOT NULL DEFAULT 'draft', budget NUMERIC, start_date TIMESTAMPTZ, end_date TIMESTAMPTZ, target_audience JSONB, target_regions TEXT[], created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
