CREATE TABLE IF NOT EXISTS public.alert_notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES public.companies(id) ON DELETE CASCADE, alert_type TEXT NOT NULL, severity TEXT NOT NULL, message TEXT NOT NULL, details JSONB, sent_via TEXT[], acknowledged BOOLEAN DEFAULT false, acknowledged_at TIMESTAMPTZ, acknowledged_by UUID, created_at TIMESTAMPTZ DEFAULT now());
