CREATE TABLE IF NOT EXISTS public.marketing_decisions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, campaign_id UUID REFERENCES public.marketing_campaigns(id), title TEXT NOT NULL, name TEXT, description TEXT, decision_type TEXT NOT NULL, guidance_level TEXT, priority TEXT DEFAULT 'medium', status TEXT NOT NULL DEFAULT 'pending', is_active BOOLEAN DEFAULT true, ai_reasoning TEXT, confidence_score NUMERIC, expected_impact JSONB, actual_results JSONB, target_regions TEXT[], custom_message TEXT, start_date TIMESTAMPTZ, end_date TIMESTAMPTZ, impressions_count INTEGER DEFAULT 0, conversions_count INTEGER DEFAULT 0, approved_by UUID, approved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.marketing_decision_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, decision_id UUID REFERENCES public.marketing_decisions(id), conversation_id UUID REFERENCES public.conversations(id), customer_id UUID REFERENCES public.customers(id), ai_run_id UUID REFERENCES public.ai_runs(id), decision_type TEXT, guidance_level TEXT, message_sent TEXT, customer_response TEXT, converted BOOLEAN DEFAULT false, converted_at TIMESTAMPTZ, conversion_value NUMERIC, notes TEXT, applied_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.marketing_template_usage (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, template_key TEXT NOT NULL, template_type TEXT, conversation_id UUID REFERENCES public.conversations(id), customer_id UUID REFERENCES public.customers(id), message_sent TEXT, sent_at TIMESTAMPTZ DEFAULT now(), conversion_status TEXT, conversion_value NUMERIC, converted_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.persuasion_tracking (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, conversation_id UUID REFERENCES public.conversations(id), customer_id UUID REFERENCES public.customers(id), strategy_used TEXT, message_sent TEXT, customer_response TEXT, was_successful BOOLEAN, conversion_value NUMERIC, emotion_before TEXT, emotion_after TEXT, notes TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.sales_scenario_tracking (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, conversation_id UUID REFERENCES public.conversations(id), customer_id UUID REFERENCES public.customers(id), scenario_type TEXT NOT NULL, scenario_key TEXT, trigger_condition TEXT, message_sent TEXT, outcome TEXT, outcome_at TIMESTAMPTZ, revenue_generated NUMERIC, products_offered TEXT[], discount_offered NUMERIC, notes TEXT, triggered_at TIMESTAMPTZ DEFAULT now());

-- Global learning
CREATE TABLE IF NOT EXISTS public.global_learned_patterns (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), pattern_type TEXT NOT NULL, sector TEXT NOT NULL, pattern_key TEXT NOT NULL, pattern_data JSONB DEFAULT '{}', success_rate NUMERIC DEFAULT 0, usage_count INTEGER DEFAULT 0, contributing_companies INTEGER DEFAULT 0, is_active BOOLEAN DEFAULT true, quality_score NUMERIC DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), UNIQUE(pattern_type, sector, pattern_key));
CREATE TABLE IF NOT EXISTS public.company_pattern_contributions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES public.companies(id) ON DELETE CASCADE, pattern_id UUID REFERENCES public.global_learned_patterns(id) ON DELETE CASCADE, local_usage_count INTEGER DEFAULT 0, local_success_rate NUMERIC DEFAULT 0, contribution_weight NUMERIC DEFAULT 1, last_synced_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now(), UNIQUE(company_id, pattern_id));
CREATE TABLE IF NOT EXISTS public.discovered_faqs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sector TEXT NOT NULL, question_pattern TEXT NOT NULL, question_variations JSONB, best_answer TEXT, answer_variations JSONB, frequency_score NUMERIC DEFAULT 0, quality_score NUMERIC DEFAULT 0, contributing_companies INTEGER DEFAULT 0, is_verified BOOLEAN DEFAULT false, auto_added_to_kb BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.prompt_optimizations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sector TEXT NOT NULL, optimization_type TEXT NOT NULL, original_prompt TEXT, optimized_prompt TEXT, improvement_metric NUMERIC DEFAULT 0, test_count INTEGER DEFAULT 0, is_active BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.successful_responses_pool (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sector TEXT NOT NULL, intent TEXT, customer_stage TEXT, customer_emotion TEXT, original_message TEXT, successful_response TEXT NOT NULL, success_indicator TEXT, quality_score NUMERIC DEFAULT 0, usage_count INTEGER DEFAULT 0, contributing_companies INTEGER DEFAULT 0, is_active BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.successful_persuasion_strategies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), sector TEXT NOT NULL, strategy_name TEXT NOT NULL, strategy_description TEXT, customer_stage TEXT, customer_emotion TEXT, total_attempts INTEGER DEFAULT 0, total_successes INTEGER DEFAULT 0, avg_conversion_rate NUMERIC DEFAULT 0, example_messages JSONB, contributing_companies INTEGER DEFAULT 0, is_active BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.learning_analytics (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES public.companies(id) ON DELETE CASCADE, period_start DATE NOT NULL, period_end DATE NOT NULL, total_interactions INTEGER DEFAULT 0, successful_responses INTEGER DEFAULT 0, modified_responses INTEGER DEFAULT 0, rejected_responses INTEGER DEFAULT 0, avg_response_quality NUMERIC DEFAULT 0, patterns_contributed INTEGER DEFAULT 0, patterns_benefited_from INTEGER DEFAULT 0, improvement_vs_previous NUMERIC DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now(), UNIQUE(company_id, period_start, period_end));

-- Sector templates
CREATE TABLE IF NOT EXISTS public.sector_marketing_templates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES public.companies(id) ON DELETE CASCADE, industry_type TEXT NOT NULL, template_key TEXT NOT NULL, template_type TEXT NOT NULL, title TEXT NOT NULL, title_ar TEXT, content TEXT NOT NULL, content_ar TEXT, variables JSONB, is_active BOOLEAN DEFAULT true, usage_count INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.sector_quick_replies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES public.companies(id) ON DELETE CASCADE, industry_type TEXT NOT NULL, shortcut TEXT NOT NULL, category TEXT NOT NULL, content TEXT NOT NULL, content_ar TEXT, is_active BOOLEAN DEFAULT true, usage_count INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.sector_sales_scenarios (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES public.companies(id) ON DELETE CASCADE, industry_type TEXT NOT NULL, scenario_key TEXT NOT NULL, scenario_type TEXT NOT NULL, title TEXT NOT NULL, title_ar TEXT, trigger_condition TEXT, response_template TEXT NOT NULL, response_template_ar TEXT, success_indicators JSONB, is_active BOOLEAN DEFAULT true, usage_count INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());

-- Social
CREATE TABLE IF NOT EXISTS public.social_channels (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, channel_type TEXT NOT NULL, channel_name TEXT NOT NULL, account_id TEXT, page_id TEXT, access_token TEXT, refresh_token TEXT, token_expires_at TIMESTAMPTZ, config JSONB, is_active BOOLEAN DEFAULT true, last_sync_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), UNIQUE(company_id, channel_type, account_id));
CREATE TABLE IF NOT EXISTS public.social_channel_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, channel_id UUID NOT NULL REFERENCES public.social_channels(id) ON DELETE CASCADE, conversation_id UUID REFERENCES public.conversations(id), external_message_id TEXT, direction TEXT NOT NULL, content TEXT, media_url TEXT, message_type TEXT DEFAULT 'text', sender_id TEXT, sender_name TEXT, status TEXT DEFAULT 'sent', metadata JSONB, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.scheduled_posts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, channel_id UUID REFERENCES public.social_channels(id), content TEXT NOT NULL, media_urls TEXT[], scheduled_at TIMESTAMPTZ NOT NULL, status TEXT DEFAULT 'scheduled', published_at TIMESTAMPTZ, error_message TEXT, ai_generated BOOLEAN DEFAULT false, created_by UUID, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());

-- Media
CREATE TABLE IF NOT EXISTS public.media_folders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, name TEXT NOT NULL, parent_id UUID REFERENCES public.media_folders(id), created_by UUID, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.media_files (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, folder_id UUID REFERENCES public.media_folders(id), name TEXT NOT NULL, file_url TEXT NOT NULL, file_type TEXT NOT NULL, file_size BIGINT DEFAULT 0, mime_type TEXT, thumbnail_url TEXT, alt_text TEXT, tags TEXT[], metadata JSONB, uploaded_by UUID, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.media_ai_settings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL UNIQUE REFERENCES public.companies(id) ON DELETE CASCADE, auto_tag BOOLEAN DEFAULT true, auto_alt_text BOOLEAN DEFAULT true, auto_categorize BOOLEAN DEFAULT true, preferred_model TEXT DEFAULT 'google/gemini-2.5-flash', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.media_usage_log (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, media_file_id UUID REFERENCES public.media_files(id), used_in TEXT, used_by UUID, context TEXT, created_at TIMESTAMPTZ DEFAULT now());

-- Misc
CREATE TABLE IF NOT EXISTS public.unanswered_questions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, conversation_id UUID REFERENCES public.conversations(id), question TEXT NOT NULL, customer_id UUID REFERENCES public.customers(id), times_asked INTEGER DEFAULT 1, status TEXT DEFAULT 'pending', suggested_answer TEXT, added_to_kb BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.landing_pages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, description TEXT, content JSONB DEFAULT '{}', meta_tags JSONB DEFAULT '{}', is_active BOOLEAN DEFAULT true, published_at TIMESTAMPTZ, created_by UUID, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.landing_page_leads (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), landing_page_id UUID REFERENCES public.landing_pages(id), name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT, company_name TEXT, company_size TEXT, industry TEXT, package_interest TEXT, message TEXT, source TEXT, utm_source TEXT, utm_medium TEXT, utm_campaign TEXT, status TEXT DEFAULT 'new', notes TEXT, assigned_to UUID, converted_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.lead_activities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), lead_id UUID NOT NULL REFERENCES public.landing_page_leads(id) ON DELETE CASCADE, activity_type TEXT NOT NULL, description TEXT, notes TEXT, outcome TEXT, user_id UUID, user_name TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.visitor_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), visitor_id TEXT, page_url TEXT, referrer TEXT, utm_source TEXT, utm_medium TEXT, utm_campaign TEXT, device_type TEXT, browser TEXT, os TEXT, country TEXT, city TEXT, ip_address TEXT, session_duration INTEGER DEFAULT 0, pages_viewed INTEGER DEFAULT 1, bounce BOOLEAN DEFAULT false, converted BOOLEAN DEFAULT false, conversion_type TEXT, started_at TIMESTAMPTZ DEFAULT now(), ended_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.page_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), session_id UUID REFERENCES public.visitor_sessions(id), event_type TEXT NOT NULL, event_name TEXT, element_id TEXT, element_text TEXT, page_url TEXT, scroll_depth INTEGER, metadata JSONB, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.section_engagement (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), session_id UUID REFERENCES public.visitor_sessions(id), section_name TEXT NOT NULL, time_spent_seconds INTEGER DEFAULT 0, scroll_in_percent NUMERIC, scroll_out_percent NUMERIC, interactions_count INTEGER DEFAULT 0, is_visible BOOLEAN DEFAULT true, first_seen_at TIMESTAMPTZ, last_seen_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());

